fn solve(n: i8, s: Vec<char>) -> i8 {
    let mut curr = 0;
    let mut max_val = 0;

    for &c in &s {
        match c {
            'I' => curr += 1,
            'D' => curr -= 1,
            _ => {} // assuming input is always 'I' or 'D'
        }
        if curr > max_val {
            max_val = curr;
        }
    }

    max_val
}

